mapper.select:
SELECT h.id, e.id AS event_id, CONCAT('E-', YEAR(COALESCE(h.opened_date, e.updated_date)), '-', LPAD(e.id, 3, '0')) AS event_number, h.id_category AS category_id, c.name AS category_name, h.status, h.status_number, h.notes AS description, h.admin_notes, h.updated_by, CASE WHEN h.operation = 1 THEN 'opened' WHEN h.operation = 2 THEN 'updated' ELSE 'updated' END AS action_type, DATE_FORMAT(h.updated_date, '%b %e, %Y %l:%i %p') AS date_formatted, h.opened_date AS event_created_date, h.updated_date AS event_updated_date, h.closed_date AS event_closed_date, CASE WHEN h.closed_date IS NOT NULL AND h.opened_date IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, h.opened_date, h.closed_date) ELSE NULL END AS duration_minutes, CASE WHEN h.closed_date IS NOT NULL AND h.opened_date IS NOT NULL THEN CASE WHEN TIMESTAMPDIFF(MINUTE, h.opened_date, h.closed_date) < 60 THEN CONCAT(TIMESTAMPDIFF(MINUTE, h.opened_date, h.closed_date), 'm') ELSE CONCAT( FLOOR(TIMESTAMPDIFF(MINUTE, h.opened_date, h.closed_date) / 60), 'h ', MOD(TIMESTAMPDIFF(MINUTE, h.opened_date, h.closed_date), 60), 'm' ) END ELSE '-' END AS duration_formatted, h.updated_date AS history_created_date
ORDER BY e.id DESC, h.id ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE status_management_category
SET is_archived = #{archived}, updated_date = NOW()
WHERE id = #{id} AND is_archived <> #{archived}

